"""Export the AI note + key charts as Markdown or a self-contained HTML file."""
from __future__ import annotations

import html
import re
from datetime import datetime
from typing import Any

import plotly.graph_objects as go

DISCLAIMER = (
    "Educational research output generated by software and an AI model from public market data. "
    "It is not investment advice or a recommendation to buy or sell any security, and the authors are not "
    "SEBI-registered Research Analysts or Investment Advisers. Data may be delayed, incomplete or wrong; "
    "verify against exchange filings before acting. Investments in securities markets are subject to market risks."
)

SECTIONS = [
    ("executive_summary", "Executive summary"), ("business_overview", "Business overview"),
    ("company_health", "Company health"), ("fundamentals", "Fundamentals"), ("valuation", "Valuation"),
    ("technical", "Technical analysis"), ("bull_case", "Bull case"), ("bear_case", "Bear case"),
    ("catalysts", "Catalysts"), ("risks", "Risks"), ("what_would_change_my_mind", "What would change the view"),
    ("monitoring_checklist", "Monitoring checklist"), ("data_gaps", "Data gaps"),
]


def _md(v: Any, depth: int = 0) -> str:
    if isinstance(v, list):
        return "\n".join(f"{'  ' * depth}- {_md(x, depth + 1) if isinstance(x, (dict, list)) else x}" for x in v)
    if isinstance(v, dict):
        out = []
        for k, x in v.items():
            label = k.replace("_", " ").capitalize()
            if isinstance(x, (dict, list)):
                out.append(f"{'  ' * depth}**{label}:**\n{_md(x, depth)}")
            else:
                out.append(f"{'  ' * depth}**{label}:** {x}")
        return "\n\n".join(out)
    return str(v)


def to_markdown(report: dict[str, Any], pack: dict[str, Any]) -> str:
    m, v = pack["meta"], report.get("verdict", {})
    lines = [f"# {m['company']} ({m['symbol']}) — AI research note",
             f"*Generated {datetime.now():%d %b %Y %H:%M} · price as of {m['price_as_of']} · source: {m['data_source']}*", "",
             f"## Verdict: {v.get('stance', '—')} · conviction {v.get('conviction', '—')} · {v.get('time_horizon', '')}",
             f"> {v.get('one_liner', '')}", ""]
    s = pack["scores"]
    lines += ["| Score | Value |", "|---|---|",
              f"| Overall model signal | {s['overall_signal'].get('score')} ({s['overall_signal'].get('label')}) |",
              f"| Fundamental health (0-100) | {s['fundamental_health_0_100']} |",
              f"| Valuation (0-100, higher = cheaper) | {s['valuation_0_100_higher_is_cheaper']} |",
              f"| Technical trend (-100..100) | {s['technical_trend_minus100_100']} |", ""]
    for key, title in SECTIONS:
        if key in report:
            lines += [f"## {title}", _md(report[key]), ""]
    a = report.get("_audit", {})
    if a.get("figures_checked"):
        lines += [f"*Number audit: {a['traced_pct']}% of {a['figures_checked']} figures traced to the computed data."
                  + (f" Unverified: {', '.join(a['unverified'])}*" if a["unverified"] else "*"), ""]
    lines += ["---", f"*{DISCLAIMER}*"]
    return "\n".join(lines)


def _md_to_html(md: str) -> str:
    out, in_list = [], False
    for raw in md.splitlines():
        line = html.escape(raw)
        line = re.sub(r"\*\*(.+?)\*\*", r"<strong>\1</strong>", line)
        line = re.sub(r"(?<!\*)\*(?!\*)(.+?)\*", r"<em>\1</em>", line)
        line = re.sub(r"\[(DATA|INFERENCE|ASSUMPTION)\]", lambda m_: f'<span class="tag {m_.group(1).lower()}">{m_.group(1)}</span>', line)
        if line.lstrip().startswith("- "):
            if not in_list:
                out.append("<ul>")
                in_list = True
            out.append(f"<li>{line.lstrip()[2:]}</li>")
            continue
        if in_list:
            out.append("</ul>")
            in_list = False
        if line.startswith("# "):
            out.append(f"<h1>{line[2:]}</h1>")
        elif line.startswith("## "):
            out.append(f"<h2>{line[3:]}</h2>")
        elif line.startswith("&gt; "):
            out.append(f"<blockquote>{line[5:]}</blockquote>")
        elif line.startswith("|"):
            cells = [c.strip() for c in raw.strip("|").split("|")]
            if set("".join(cells)) <= set("-: "):
                continue
            out.append("<tr>" + "".join(f"<td>{html.escape(c)}</td>" for c in cells) + "</tr>")
        elif line.strip() == "---":
            out.append("<hr>")
        elif line.strip():
            out.append(f"<p>{line}</p>")
    if in_list:
        out.append("</ul>")
    body = "\n".join(out)
    return re.sub(r"((?:<tr>.*?</tr>\n?)+)", r"<table>\1</table>", body, flags=re.S)


def to_html(report: dict[str, Any], pack: dict[str, Any], figures: list[go.Figure]) -> str:
    body = _md_to_html(to_markdown(report, pack))
    charts = "".join(
        f'<div class="chart">{fig.to_html(full_html=False, include_plotlyjs="cdn" if i == 0 else False)}</div>'
        for i, fig in enumerate(figures)
    )
    title = html.escape(f"{pack['meta']['company']} — research note")
    return f"""<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>{title}</title><style>
body{{background:#151514;color:#f0efec;font-family:Inter,Segoe UI,system-ui,sans-serif;max-width:1100px;margin:0 auto;padding:24px 16px;line-height:1.55}}
h1{{font-size:26px}} h2{{font-size:19px;margin-top:28px;border-bottom:1px solid #33332f;padding-bottom:4px}}
blockquote{{border-left:3px solid #3987e5;margin:0;padding:6px 14px;background:#1f1f1d}}
table{{border-collapse:collapse;margin:10px 0}} td{{border:1px solid #33332f;padding:5px 10px}}
.tag{{font-size:11px;font-weight:600;padding:1px 6px;border-radius:4px;margin-right:4px}}
.tag.data{{background:#1d3320;color:#7fd67f}} .tag.inference{{background:#1c2c45;color:#8fb8ef}} .tag.assumption{{background:#3a2f12;color:#f2c25b}}
.chart{{margin:18px 0}} em{{color:#a3a29a}} hr{{border:0;border-top:1px solid #33332f}}
</style></head><body>{body}<h2>Charts</h2>{charts}</body></html>"""
